name: PR Issue Link Check

on:
  pull_request:
    types: [opened, edited, synchronize, reopened]

permissions:
  pull-requests: read
  issues: read

jobs:
  check-issue-link:
    runs-on: ubuntu-latest
    steps:
      - name: Check for issue link in PR title or body
        id: check-link
        uses: actions/github-script@v7
        with:
          script: |
            const pr = context.payload.pull_request;
            const title = pr.title;
            const body = pr.body || '';
            const combinedText = `${title}\n${body}`;

            // Pattern to match standard GitHub issue closing keywords
            // Matches: Fixes #123, Closes #456, Resolves #789, etc.
            // Also matches just #123 if not preceded by a word character to avoid false positives in code blocks sometimes, 
            // but strictly speaking, the request asks for specific patterns.
            // Let's look for the specific keywords mentioned in the docs: Fixes, Closes, Resolves
            // And also general #number references if they look like issue links.

            const issueLinkPattern = /(?:fixes|closes|resolves|refs?)\s*#(\d+)/i;
            const matches = combinedText.match(issueLinkPattern);

            if (!matches) {
              core.setFailed('No valid issue link found in the PR title or description. Please link this PR to an issue using keywords like "Fixes #123", "Closes #456", or "Resolves #789".');
              return;
            }

            const issueNumber = matches[1];
            core.info(`Found potential issue link: #${issueNumber}`);

            // Verify the issue exists
            try {
              const issue = await github.rest.issues.get({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issueNumber
              });

              if (issue.data.state === 'closed') {
                core.warning(`Issue #${issueNumber} is already closed. Ensure this is intended.`);
              }

              core.info(`Issue #${issueNumber} exists and is valid.`);
            } catch (error) {
              if (error.status === 404) {
                core.setFailed(`Issue #${issueNumber} does not exist in this repository.`);
              } else {
                core.setFailed(`Error checking issue #${issueNumber}: ${error.message}`);
              }
            }
